<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Campaign; use Illuminate\Http\Request;
class CampaignController extends Controller { public function index(){return Campaign::query()->orderByDesc('active')->orderBy('name')->get();} public function store(Request $r){return response()->json(Campaign::create($this->data($r)),201);} public function update(Request $r,Campaign $campaign){$campaign->update($this->data($r));return $campaign;} public function destroy(Campaign $campaign){$campaign->delete();return response()->noContent();} private function data(Request $r){return $r->validate(['name'=>['required','string','max:255'],'channel_id'=>['nullable','exists:channels,id'],'starts_on'=>['nullable','regex:/^1[34]\\d{2}-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])$/'],'ends_on'=>['nullable','regex:/^1[34]\\d{2}-(0[1-9]|1[0-2])-(0[1-9]|[12]\\d|3[01])$/'],'budget'=>['nullable','numeric','min:0'],'note'=>['nullable','string'],'active'=>['boolean']]);} }
